 static void Write(StringBuilder b,object o){if(o==null){b.Append("null");return;}var s=o as string;if(s!=null){b.Append('"');foreach(char c in s){switch(c){case '"':b.Append("\\\"");break;case '\\':b.Append("\\\\");break;case '\n':b.Append("\\n");break;case '\r':b.Append("\\r");break;case '\t':b.Append("\\t");break;default:if(c<32)b.Append("\\u"+((int)c).ToString("x4"));else b.Append(c);break;}}b.Append('"');return;}var d=o as IDictionary<string,object>;if(d!=null){b.Append('{');bool comma=false;foreach(var x in d){if(comma)b.Append(',');comma=true;Write(b,x.Key);b.Append(':');Write(b,x.Value);}b.Append('}');return;}var a=o as IEnumerable;if(a!=null){b.Append('[');bool comma=false;foreach(object x in a){if(comma)b.Append(',');comma=true;Write(b,x);}b.Append(']');return;}if(o is bool){b.Append((bool)o?"true":"false");return;}b.Append(Convert.ToString(o,CultureInfo.InvariantCulture));}
 sealed class Reader {
