  public object Value(int depth){if(depth>32)throw new ArgumentException("JSON nesting limit");White();if(i>=s.Length)throw new ArgumentException("Truncated JSON");char c=s[i];if(c=='"')return Str();if(c=='{'){i++;var d=new Dictionary<string,object>(StringComparer.Ordinal);White();if(i<s.Length&&s[i]=='}'){i++;return d;}while(true){White();if(i>=s.Length||s[i]!='"')throw new ArgumentException("Expected member");string k=Str();if(d.ContainsKey(k))throw new ArgumentException("Duplicate JSON member "+k);Need(':');d.Add(k,Value(depth+1));White();if(i<s.Length&&s[i]=='}'){i++;return d;}Need(',');}}if(c=='['){i++;var a=new List<object>();White();if(i<s.Length&&s[i]==']'){i++;return a;}while(true){a.Add(Value(depth+1));White();if(i<s.Length&&s[i]==']'){i++;return a;}Need(',');}}foreach(string token in new[]{"true","false","null"})if(s.Substring(i).StartsWith(token,StringComparison.Ordinal)){i+=token.Length;return token=="null"?null:(object)(token=="true");}int start=i;if(s[i]=='-')i++;if(i>=s.Length)throw new ArgumentException("Bad JSON number");if(s[i]=='0')i++;else{if(s[i]<'1'||s[i]>'9')throw new ArgumentException("Bad JSON value");while(i<s.Length&&char.IsDigit(s[i]))i++;}if(i<s.Length&&s[i]=='.'){i++;int at=i;while(i<s.Length&&char.IsDigit(s[i]))i++;if(i==at)throw new ArgumentException("Bad fraction");}if(i<s.Length&&(s[i]=='e'||s[i]=='E')){i++;if(i<s.Length&&(s[i]=='+'||s[i]=='-'))i++;int at=i;while(i<s.Length&&char.IsDigit(s[i]))i++;if(i==at)throw new ArgumentException("Bad exponent");}double n;if(!double.TryParse(s.Substring(start,i-start),NumberStyles.Float,CultureInfo.InvariantCulture,out n)||double.IsInfinity(n)||double.IsNaN(n))throw new ArgumentException("Invalid number");return n;}
  string Str(){i++;var b=new StringBuilder();while(i<s.Length){char c=s[i++];if(c=='"'){string result=b.ToString();for(int k=0;k<result.Length;k++){if(char.IsHighSurrogate(result[k])){if(k+1>=result.Length||!char.IsLowSurrogate(result[++k]))throw new ArgumentException("Invalid Unicode");}else if(char.IsLowSurrogate(result[k]))throw new ArgumentException("Invalid Unicode");}return result;}if(c<32)throw new ArgumentException("Control in string");if(c!='\\'){b.Append(c);continue;}if(i>=s.Length)throw new ArgumentException("Truncated escape");switch(c=s[i++]){case '"':case '\\':case '/':b.Append(c);break;case 'b':b.Append('\b');break;case 'f':b.Append('\f');break;case 'n':b.Append('\n');break;case 'r':b.Append('\r');break;case 't':b.Append('\t');break;case 'u':if(i+4>s.Length)throw new ArgumentException("Truncated Unicode");int n;if(!int.TryParse(s.Substring(i,4),NumberStyles.HexNumber,CultureInfo.InvariantCulture,out n))throw new ArgumentException("Bad Unicode");i+=4;b.Append((char)n);break;default:throw new ArgumentException("Bad escape");}}throw new ArgumentException("Unterminated string");}
